using System.Collections.ObjectModel;using System.Windows.Input;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class AlertsViewModel:ObservableObject{readonly AgentDashboardClient c;bool loading,marking;string? error,status;int unread;public ObservableCollection<AlertRow> Items{get;}=[];public bool IsLoading{get=>loading;private set=>Set(ref loading,value);}public bool IsMarking{get=>marking;private set=>Set(ref marking,value);}public string? Error{get=>error;private set=>Set(ref error,value);}public string? Status{get=>status;private set=>Set(ref status,value);}public int Unread{get=>unread;private set=>Set(ref unread,value);}public ICommand MarkAllReadCommand{get;}public AlertsViewModel(AgentDashboardClient c){this.c=c;MarkAllReadCommand=new AsyncCommand(MarkAllReadAsync);}public async Task LoadAsync(){IsLoading=true;Error=null;try{var x=await c.AlertsAsync();if(x is null)return;Unread=x.UnreadCount;Items.Clear();foreach(var a in x.Alerts)Items.Add(new(a.Key,Severity(a.Severity),Category(a.Category),a.DatabaseName,a.Title,a.Message,PersianDateFormatter.Format(a.OccurredAtUtc),a.IsRead?"خوانده‌شده":"جدید",a.IsRead));}catch(Exception e){Error=e.Message;}finally{IsLoading=false;}}async Task MarkAllReadAsync(){var keys=Items.Where(x=>!x.IsRead).Select(x=>x.Key).ToArray();if(keys.Length==0){Status="هشدار خوانده‌نشده‌ای وجود ندارد.";return;}IsMarking=true;try{await c.MarkAlertsReadAsync(keys);Status="همه هشدارها خوانده شدند.";await LoadAsync();}catch(Exception e){Status=$"خطا: {e.Message}";}finally{IsMarking=false;}}static string Severity(string s)=>s.ToLowerInvariant() switch{"critical"=>"بحرانی","error"=>"خطا","warning"=>"هشدار","info"=>"اطلاعات",_=>s};static string Category(string s)=>s.ToLowerInvariant() switch{"backup"=>"بکاپ","verification"=>"بررسی سلامت","replica"=>"پشتیبان","storage"=>"ذخیره‌سازی","database"=>"دیتابیس",_=>s};}internal sealed record AlertRow(string Key,string Severity,string Category,string Database,string Title,string Message,string Time,string State,bool IsRead);